import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.Stack;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine().trim());int[] a = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {a[i] = Integer.parseInt(st.nextToken());}int[] left = new int[n];int[] right = new int[n];Stack<Integer> stack = new Stack<Integer>();for (int i = 0; i < n; i++) {while (!stack.isEmpty() && a[stack.peek()] < a[i]) {stack.pop();}if (stack.isEmpty()) {left[i] = -1;} else {left[i] = stack.peek();}stack.push(i);}stack.clear();for (int i = n - 1; i >= 0; i--) {while (!stack.isEmpty() && a[stack.peek()] < a[i]) {stack.pop();}if (stack.isEmpty()) {right[i] = n;} else {right[i] = stack.peek();}stack.push(i);}long count = 0;for (int i = 0; i < n; i++) {if (left[i] != -1) {count++;}if (right[i] != n) {count++;}}System.out.println(count);}}